using UnityEngine;
namespace COW.GamePlay
{
    public partial class SceneEditBoxSelectTool
    {
        public static Texture2D MzBrandTexture;
        public static bool MzBrandFailed;
        // Rasterized once from Segoe UI Semibold / Cambria Math. No font files
        // or HTML runtime are embedded. Exact title remains in the bytecode.
        public static bool MzBrandTitle(float x,float y,float width)
        {
            if(MzBrandTexture==null&&!MzBrandFailed){try{MzBrandTexture=MzPng("",FilterMode.Bilinear);}catch(System.Exception){MzBrandFailed=true;}}
            if(MzBrandTexture==null)return false;GUI.DrawTexture(new Rect(x,y,width,32),MzBrandTexture);return true;
        }
    }
}
